SELECT definition_id AS definitionId, model_json AS modelJson, version, lock_version AS lockVersion
FROM wf_process_definition WHERE tenant_id = #{tenantId} AND process_key = #{processKey}
  AND deleted = 0 AND status = 'PUBLISHED' AND is_latest = 1 AND is_archived = 0

SELECT * FROM hr_employee WHERE tenant_id = #{tenantId} AND id IN
#{employeeId}
ORDER BY id FOR UPDATE


SELECT COUNT(*) FROM hr_overtime_request request_row WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId}
  AND deleted = 0 AND start_time < #{to} AND end_time > #{from}
  AND request_id <> #{excludedId}
  AND (status IN ('SUBMITTED','PENDING','APPROVING','APPROVED') OR (status = 'CANCELLED' AND ))

SELECT * FROM hr_time_request WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId} AND deleted = 0
  AND request_type = 'LEAVE' AND status IN ('SUBMITTED','PENDING','APPROVING','APPROVED')
  AND start_time < #{to} AND end_time > #{from}


SELECT COUNT(*) FROM hr_shift_request request_row WHERE tenant_id = #{tenantId}
  AND (employee_id = #{employeeId} OR swap_employee_id = #{employeeId}) AND deleted = 0
  AND from_date <= #{to} AND from_date >= #{from}
  AND request_id <> #{excludedId}
  AND (status IN ('WAITING_ACCEPTANCE','PENDING','APPROVING') OR (status = 'APPROVED' AND application_status = 'PENDING')
    OR (status = 'CANCELLED' AND ))

SELECT COALESCE(SUM(actual_minutes), 0) FROM hr_overtime_request WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId}
  AND deleted = 0 AND status IN ('SUBMITTED','PENDING','APPROVING','APPROVED') AND work_date BETWEEN #{from} AND #{to}
  AND request_id <> #{excludedId}

SELECT id, tenant_id, change_no, employee_id, change_type, change_amount AS change_amount_text,
       effective_date, status, deleted, salary_component_id, payroll_period_id, source_biz_type, source_biz_id
FROM hr_comp_change WHERE tenant_id = #{tenantId} AND source_biz_type = 'HR_OVERTIME' AND source_biz_id = #{requestId}

SELECT COUNT(*) FROM hr_overtime_request WHERE tenant_id = #{tenantId} AND payroll_period_id = #{periodId}
  AND deleted = 0 AND settle_mode = 'PAY' AND status IN ('SUBMITTED','PENDING','APPROVING','APPROVED')
  AND settlement_status NOT IN ('SETTLED','REJECTED')
  AND employee_id = #{employeeId}

SELECT COUNT(*) FROM hr_overtime_request WHERE tenant_id = #{tenantId} AND leave_period_id = #{periodId}
  AND deleted = 0 AND settle_mode = 'COMPENSATORY' AND status IN ('SUBMITTED','PENDING','APPROVING','APPROVED')
  AND settlement_status NOT IN ('SETTLED','REJECTED')

SELECT COUNT(*) FROM hr_attendance_monthly WHERE tenant_id = #{tenantId} AND employee_id = #{employeeId}
  AND year = CAST(SUBSTRING(#{month}, 1, 4) AS UNSIGNED)
  AND month = CAST(SUBSTRING(#{month}, 6, 2) AS UNSIGNED) AND status = 'CONFIRMED'

SELECT * FROM hr_schedule_assignment WHERE tenant_id = #{tenantId} AND source_shift_request_id IS NOT NULL
  AND source_shift_request_id = #{requestId}
ORDER BY id
